INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 29, 'theory', 'Quiz: std traits');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 0, 'Why does f64 implement PartialEq and PartialOrd, but not Eq and Ord?', '["because floating-point numbers are too large", "because of NaN: it is not equal even to itself and is incomparable", "because f64 has no default value", "because f64 is Copy"]', 1, 'Eq and Ord require total equality and total order; NaN breaks both.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 1, 'What do you get automatically if you implement From<A> for B?', '["Into<B> for A", "TryFrom<B> for A", "Clone for B", "Default for B"]', 0, 'Into for A is implemented for you: write From, use into().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 2, 'Which closure trait is the strictest (demands the most from the closure)?', '["FnOnce", "FnMut", "Fn", "they are equal"]', 2, 'Fn only reads and can be called many times; such a closure fits FnMut and FnOnce as well.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 3, 'What does consistency between Hash and Eq guarantee?', '["different values give different hashes", "the hash does not depend on the value", "the hash is always zero", "equal values give the same hash"]', 3, 'Otherwise a HashMap will not find a key that is stored in it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 4, 'Why is Rc<T> not Send?', '["because T may be a string", "because Rc''s reference counter is not atomic", "because Rc stores references", "because Rc cannot be copied"]', 1, 'For threads there is Arc, with an atomic counter.');
